#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: восстановление прод-VPS для kislyakov.pro (Dossier).
# Обсуждено 2026-10-12 — .scratch/skills-adoption/issues/01-provision-vps-wizard.md
# Библиотека выше маркера побайтово совпадает с шаблоном /wizard: не трогаем.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=11

# Хелперы удалённого доступа (ниже маркера — допустимо).
remote() { ssh "root@${VPS_HOST}" "$1"; }
remote_run() { ssh "root@${VPS_HOST}" 'bash -s'; }
scp_to() { scp "$1" "root@${VPS_HOST}:$2"; }

REPO_URL="https://github.com/skislyakow/dossier.git"
APP_DIR="/root/dossier"
STATIC_DIR="/var/www/dossier/static"

banner "Восстановление VPS — kislyakov.pro (Dossier)"

stage "Сервер и публичный адрес"
say "Нужен VPS с Ubuntu 24.04 (провайдер — reg.ru). Возьми его публичный IP."
warn "Этот VPS общий: на нём уже крутятся другие проекты. Wizard ставит ТОЛЬКО"
warn "nginx-vhost и systemd-юнит для Dossier — прочие сайты не трогает."
open_url "https://www.reg.ru/user/account/#/vps/"
ask VPS_HOST "Публичный IP или hostname VPS:"
write_env VPS_HOST "$VPS_HOST"

stage "DNS (reg.ru)"
say "Пропиши A-записи, чтобы домен указывал на этот сервер:"
step "A  @    → ${VPS_HOST}"
step "A  www  → ${VPS_HOST}   (либо CNAME www → kislyakov.pro)"
open_url "https://www.reg.ru/user/account/#/zones/"
note "Если DNS уже настроен — просто нажми Enter."
pause "Нажми Enter, когда записи сохранены."

stage "SSH-доступ root"
ask SSH_KEY_PATH "Путь к приватному ключу для root [~/.ssh/id_rsa]:"
if [[ -z "$SSH_KEY_PATH" ]]; then SSH_KEY_PATH="$HOME/.ssh/id_rsa"; fi
write_env SSH_KEY_PATH "$SSH_KEY_PATH"
step "Если ключа ещё нет: ssh-keygen -t ed25519 -f ~/.ssh/id_rsa"
step "Публичный ключ (~/.ssh/id_rsa.pub) положи в /root/.ssh/authorized_keys на VPS"
pause "Проверю соединение по Enter..."
if remote "echo ok" >/dev/null 2>&1; then
  say "SSH работает ✓"
else
  warn "SSH не отвечает — проверь ключ/DNS и перезапусти wizard."
fi

stage "GitHub secrets (CI)"
say "Впишу секреты, которые читает .github/workflows/deploy.yml:"
set_secret VPS_HOST "$VPS_HOST"
set_secret VPS_SSH_KEY "$(cat "$SSH_KEY_PATH")"

stage "Базовые пакеты на VPS"
warn "Это общий сервер — apt только доустанавливает пакеты, ничего не удаляет."
say "nginx, git, Python, certbot и библиотеки WeasyPrint для PDF-резюме."
if confirm "Установить пакеты на ${VPS_HOST}?"; then
  remote_run <<REMOTE
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
apt-get update
apt-get install -y --no-install-recommends \\
  python3 python3-venv python3-pip git nginx certbot python3-certbot-nginx \\
  libpango-1.0-0 libpangoft2-1.0-0 libharfbuzz-subset0 \\
  fonts-dejavu-core fonts-dejavu-extra
command -v uv >/dev/null 2>&1 || curl -LsSf https://astral.sh/uv/install.sh | sh
REMOTE
else
  warn "пропущено — установи пакеты вручную"
fi

stage "Код и секреты приложения"
say "Клонирую репозиторий в ${APP_DIR} и создаю /etc/dossier/dossier.env."
DJANGO_SECRET_KEY=$(python3 -c 'import secrets; print(secrets.token_urlsafe(50))')
remote "install -d -m 700 /etc/dossier && printf 'DJANGO_SECRET_KEY=%s\n' '${DJANGO_SECRET_KEY}' > /etc/dossier/dossier.env && chmod 600 /etc/dossier/dossier.env"
step "Опционально: GitHub token поднимает лимит GitHub API 60→5000/ч."
ask_secret GITHUB_TOKEN "GITHUB_TOKEN (Enter — пропустить):"
if [[ -n "$GITHUB_TOKEN" ]]; then
  printf 'GITHUB_TOKEN=%s\n' "$GITHUB_TOKEN" | ssh "root@${VPS_HOST}" "cat >> /etc/dossier/dossier.env"
  say "токен записан в /etc/dossier/dossier.env ✓"
fi
remote_run <<REMOTE
set -euo pipefail
if [ -d "${APP_DIR}/.git" ]; then
  git -C "${APP_DIR}" fetch origin main
  git -C "${APP_DIR}" checkout -f -B main origin/main
else
  git clone "${REPO_URL}" "${APP_DIR}"
fi
REMOTE

stage "systemd-юнит"
scp_to deploy/dossier.service /etc/systemd/system/dossier.service
remote_run <<'REMOTE'
set -euo pipefail
systemctl daemon-reload
systemctl enable dossier
REMOTE

stage "Nginx-vhost"
scp_to deploy/nginx.conf /etc/nginx/sites-available/dossier
remote_run <<'REMOTE'
set -euo pipefail
ln -sf /etc/nginx/sites-available/dossier /etc/nginx/sites-enabled/dossier
nginx -t
systemctl reload nginx
REMOTE

stage "TLS (Let's Encrypt)"
ask LETSENCRYPT_EMAIL "Email для Let's Encrypt:"
remote "certbot --nginx -d kislyakov.pro -d www.kislyakov.pro --non-interactive --agree-tos -m '${LETSENCRYPT_EMAIL}' --redirect" \
  || warn "certbot упал — сначала убедись, что DNS уже указывает на этот VPS"

stage "Первый деплой и статика"
say "Ставлю зависимости, миграции, PDF-резюме, собираю статику."
remote_run <<REMOTE
set -euo pipefail
cd "${APP_DIR}"
export PATH="\$HOME/.local/bin:\$PATH"
uv sync --frozen --no-dev
uv run manage.py migrate --noinput
uv run manage.py createcachetable
RESUME_AUTOGEN=1 uv run manage.py generate_resume
uv run manage.py collectstatic --noinput
chown -R www-data:www-data "${STATIC_DIR}"
systemctl restart dossier
REMOTE

stage "Проверка"
say "Дальше пуши в main деплоятся автоматически (GitHub Actions)."
step "Проверка прод-контура: ./tools/smoke.sh https://kislyakov.pro"
step "Свежесть статики байт-в-байт проверяет джоба verify в CI."
open_url "https://kislyakov.pro/"

finish
